# POST /api/sheets/{sheetId}/people/import — add a person per pasted line. Body {"text":"..."}, lines of
# name,grade,terms,contact (the last two may be absent or blank). Every line is checked first by the person form's
# rules: 400 for a bad line, a name or contact already in use, or one repeated in the import (ignoring case) — and
# then nothing is stored. Each person is recorded as PERSON_ADDED, as the form records one. Responds {"added":n}.
viewer:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: archived
  govern: [ transaction ]
archived:
  class: net.officefloor.hq.app.sheet.RefuseArchived
  next: snapshot
  govern: [ transaction ]
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  next: validate
  govern: [ transaction ]
validate:
  class: net.officefloor.hq.app.person.ValidateImport
  next: add
  govern: [ transaction ]
add:
  class: net.officefloor.hq.app.person.AddImportedPeople
  next: respond
  govern: [ transaction ]
respond:
  class: net.officefloor.hq.app.person.RespondWithImported
  govern: [ transaction ]
package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateImport {
    // Every line is checked before any is added, by the person form's rules: name,grade,terms,contact (the last two may be
    // absent or blank). A name already used on the sheet's tree as a name or alias, or a contact already on the sheet, is
    // refused, as is a name or contact repeated in the import (ignoring case). Blank lines are skipped; an import with no
    // line is refused.
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody ImportRequest body, People people,
            Out<ImportedPeople> out) throws InvalidPersonException {
        String sheet = sheetId.trim();
        String text = body == null || body.text() == null ? "" : body.text();
        List<PersonRequest> lines = new ArrayList<>();
        Set<String> names = new HashSet<>();
        Set<String> contacts = new HashSet<>();
        int n = 0;
        for (String line : text.split("\\r?\\n")) {
            n++;
            if (line.isBlank()) {
                continue;
            }
            String[] fields = line.split(",", -1);
            if (fields.length < 2 || fields.length > 4) {
                throw new InvalidPersonException("Line " + n + ": type name,grade,terms,contact.");
            }
            try {
                PersonRequest request = PersonRules.parse(new PersonRequest(fields[0], fields[1], null, null,
                        fields.length > 2 ? fields[2] : "", fields.length > 3 ? fields[3] : ""));
                if (!names.add(request.name().toLowerCase(Locale.ROOT))) {
                    throw new InvalidPersonException("The name " + request.name() + " is given twice in the import.");
                }
                if (request.contact() != null && !contacts.add(request.contact())) {
                    throw new InvalidPersonException("The contact " + request.contact() + " is given twice in the import.");
                }
                if (people.nameTaken(sheet, request.name(), -1)) {
                    throw new InvalidPersonException("The name is already in use.");
                }
                if (request.contact() != null && people.contactTaken(sheet, request.contact(), -1)) {
                    throw new InvalidPersonException("The contact is already in use.");
                }
                lines.add(request);
            } catch (InvalidPersonException e) {
                throw new InvalidPersonException("Line " + n + ": " + e.getMessage());
            }
        }
        if (lines.isEmpty()) {
            throw new InvalidPersonException("Paste at least one line of name,grade,terms,contact.");
        }
        out.set(new ImportedPeople(lines));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithImported {
    public void respond(@Val ImportResponse imported, ObjectResponse<ImportResponse> response) {
        response.send(imported);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Figures;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupLines;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class AddImportedPeople {
    // Each checked line is added in order as the person form adds one: PERSON_ADDED, then its ROLLUP lines.
    public void add(@PathVariable("sheetId") String sheetId, @Val ImportedPeople imported, @Val Figures before,
            People people, Rollup rollup, ServerHttpConnection connection, Audit audit, Out<ImportResponse> result) {
        String sheet = sheetId.trim();
        String user = Audit.user(connection);
        Figures figures = before;
        for (PersonRequest request : imported.people()) {
            new AuditPersonAdded().audit(people.add(sheet, request), connection, audit);
            figures = RollupLines.record(sheet, user, figures, rollup, audit);
        }
        result.set(new ImportResponse(imported.people().size()));
    }
}
package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AuditPersonEdited {
    public void audit(@Val Person loaded, @Val PersonResponse edited,
            ServerHttpConnection connection, Audit audit) {
        // terms= only when the save changed the person's own terms ("" when it cleared them); contact= likewise.
        List<String> fields = new ArrayList<>(List.of("name=" + edited.name(), "grade=" + edited.grade()));
        if (!Objects.equals(loaded.terms(), edited.terms())) {
            fields.add("terms=" + (edited.terms() == null ? "" : edited.terms()));
        }
        if (!Objects.equals(loaded.contact(), edited.contact())) {
            fields.add("contact=" + (edited.contact() == null ? "" : edited.contact()));
        }
        audit.record(Audit.line("PERSON_EDITED", loaded.sheetId(), Audit.user(connection), fields.toArray(String[]::new)));
    }
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson, RefusedError } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { peopleKey } from './peopleQuery';
import { useUser } from '../session/useUser';

/**
 * The import box: lines of name,grade,terms,contact each add a person, in order, as the person form adds one. The
 * server checks every line by the form's rules first (a name or contact repeated in the import is refused too) and
 * adds nothing when any is refused. Shows how many were added.
 */
function ImportPeople({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const [text, setText] = useState('');
  const [error, setError] = useState('');
  const [added, setAdded] = useState('');
  const once = useSubmitOnce();
  const importPeople = useMutation({
    mutationFn: (body: { text: string }) =>
      postJson<{ added: number }>(`/api/sheets/${encodeURIComponent(sheetId)}/people/import`, body, user),
    onSuccess: async (res) => {
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      setText('');
      setAdded(String(res.added));
    },
    onError: (e) =>
      setError(e instanceof RefusedError ? e.message : 'The people could not be imported: check every line.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    setAdded('');
    if (text.trim() === '') {
      setError('Paste at least one line of name,grade,terms,contact.');
      return;
    }
    once(() => importPeople.mutateAsync({ text }));
  };

  return (
    <form data-testid="import-box" onSubmit={submit}>
      <label>
        Import people (name,grade,terms,contact){' '}
        <textarea
          data-testid="import-people"
          rows={4}
          value={text}
          onChange={(e) => {
            setText(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="import-submit" disabled={importPeople.isPending}>
        Import
      </button>{' '}
      Added: <span data-testid="import-added">{added}</span>
      {error && <p data-testid="import-error">{error}</p>}
    </form>
  );
}

// Below the person form; keyed by sheet, so pasted text, a count or an error never carries over.
export const contribution = SheetPanel.fill({
  order: 10.5,
  Component: ({ sheetId }) => <ImportPeople key={sheetId} sheetId={sheetId} />,
});

