package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePerson {

    // The name is kept without surrounding spaces; a blank one is refused.
    public void validate(@RequestBody PersonRequest body, Out<PersonRequest> request) throws InvalidPersonException {
        request.set(PersonRules.parse(body));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") long personId,
            People people, Out<Person> personOut) throws PersonNotFoundException {
        Person person = people.find(sheetId.trim(), personId);
        if (person == null) {
            throw new PersonNotFoundException("No person " + personId + " on this sheet.");
        }
        personOut.set(person);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class ApplyPerson {
    // Person is a record, so the edited person is published in place of the loaded one. The edit is
    // refused when the version its form loaded is not the stored one: someone else saved it since.
    // The form's grade is given from its from-date (the sheet's today when blank), keeping the grades
    // already given; a save leaving the grade in force today as it is, with no from-date, gives none.
    // The name is refused when anyone else on the sheet's tree uses it as a name or alias.
    public void apply(@Val PersonRequest request, @Val Person person, People people, Sheets sheets,
            Out<PersonResponse> responseOut) throws InvalidPersonException, PersonConflictException {
        if (request.version() != null && request.version() != person.version()) {
            throw new PersonConflictException("Someone else has saved this person since it was opened.");
        }
        if (people.nameTaken(person.sheetId(), request.name(), person.id())) {
            throw new InvalidPersonException("The name is already in use.");
        }
        // A person whose alias clashes across the sheet's tree is refused every edit (only a rename frees the name).
        if (people.aliasClashes(person)) {
            throw new InvalidPersonException("An alias of theirs is already in use on the sheet's tree.");
        }
        if (request.contact() != null && people.contactTaken(person.sheetId(), request.contact(), person.id())) {
            throw new InvalidPersonException("The contact is already in use.");
        }
        LocalDate today = sheets.today(person.sheetId());
        Person edited = person.with(request);
        if (!people.save(edited)) {
            throw new PersonConflictException("Someone else has saved this person since it was opened.");
        }
        if (request.gradeFrom() != null || !request.grade().equals(person.gradeOn(today))) {
            LocalDate from = request.gradeFrom() != null ? LocalDate.parse(request.gradeFrom()) : today;
            people.gradeFrom(person.id(), from, request.grade());
            List<DatedGrade> dated = new ArrayList<>(edited.dated().stream().filter(d -> !d.from().equals(from)).toList());
            dated.add(new DatedGrade(from, request.grade()));
            dated.sort(Comparator.comparing(DatedGrade::from));
            edited = new Person(edited.id(), edited.sheetId(), edited.name(), edited.grade(), edited.version(),
                    edited.retiredFrom(), edited.holds(), List.copyOf(dated), edited.terms(), edited.contact(), edited.aliases());
        }
        responseOut.set(PersonResponse.from(edited, today));
    }
}
package net.officefloor.hq.app.person;

/**
 * The body of an add or an edit of a person: the name as typed and the grade (A, B or C). An edit
 * also names the {@code version} its form loaded (null on an add), and {@code gradeFrom}, the date
 * (yyyy-mm-dd) the grade is given from, blank for the sheet's today. An add's grade is the first one,
 * which applies from the beginning of time, so it ignores {@code gradeFrom}. {@code terms} are the person's own
 * terms, a whole number of days, null (blank) for none. {@code contact} is the person's contact, trimmed and
 * lower-cased, null (blank) for none.
 */
public record PersonRequest(String name, String grade, Long version, String gradeFrom, String terms, String contact) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;
import java.util.Set;
import java.util.regex.Pattern;

/** The person form's rules, shared by the form and the people import. */
final class PersonRules {

    private PersonRules() {
    }

    private static final DateTimeFormatter ISO = DateTimeFormatter.ofPattern("uuuu-MM-dd")
            .withResolverStyle(ResolverStyle.STRICT);

    private static final Pattern DAYS = Pattern.compile("\\d{1,4}");

    private static final Set<String> GRADES = Set.of("A", "B", "C");

    /** The request as it is stored; the name is kept without surrounding spaces, a blank one is refused. */
    public static PersonRequest parse(PersonRequest body) throws InvalidPersonException {
        String name = body == null || body.name() == null ? "" : body.name().trim();
        String grade = body == null || body.grade() == null ? "" : body.grade().trim();
        if (name.isEmpty()) {
            throw new InvalidPersonException("Type a name.");
        }
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("The grade must be A, B or C.");
        }
        // A blank from-date is kept null: the sheet's today, filled in when stored.
        String from = body.gradeFrom() == null ? "" : body.gradeFrom().trim();
        if (!from.isEmpty()) {
            try {
                LocalDate.parse(from, ISO);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("Not a date (yyyy-mm-dd): " + from);
            }
        }
        String terms = body.terms() == null ? "" : body.terms().trim();
        if (!terms.isEmpty() && !DAYS.matcher(terms).matches()) {
            throw new InvalidPersonException("The terms must be a whole number of days, 0 or more.");
        }
        // The contact is kept trimmed and lower-cased; a blank one is none.
        String contact = body.contact() == null ? "" : body.contact().trim().toLowerCase(java.util.Locale.ROOT);
        return new PersonRequest(name, grade, body.version(), from.isEmpty() ? null : from,
                terms.isEmpty() ? null : Integer.toString(Integer.parseInt(terms)), contact.isEmpty() ? null : contact);
    }
}
